for sector, meta in META.items():
    print(f"Generating {sector} ({meta['name']})...")
    base_dir = os.path.join(BASE, sector)
    for idx, (phase, pnum) in enumerate(zip(PHASES, PHASE_NUMS)):
        phase_dir = os.path.join(base_dir, phase)
        os.makedirs(phase_dir, exist_ok=True)
        content = gen(meta, idx+1, phase, pnum)
        fp = os.path.join(phase_dir, f"{phase}.md")
        with open(fp, 'w', encoding='utf-8') as f:
            f.write(content)
    print(f"  Generated 22 files")
